import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Select,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type {
  FinancialStatementNotesCompany,
  FinancialStatementNotesSection,
} from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './ThuyetMinhBctcPage.module.css';

const TEST_ID = 'erp-thuyet-minh-bctc';
const PAGE_ID = 'baocao-thuyet-minh-bctc';
const TITLE = 'Thuyết minh báo cáo tài chính';
const DEFAULT_TEMPLATE = 'GLTC20_TT200';
const TEMPLATE_ALLOW = new Set([DEFAULT_TEMPLATE]);

const DATE_TYPE_OPTIONS = [
  ...Array.from({ length: 12 }, (_, i) => {
    const v = String(i + 1).padStart(2, '0');
    return { value: v, label: `Tháng ${i + 1}` };
  }),
  { value: '13', label: 'Quý 1' },
  { value: '14', label: 'Quý 2' },
  { value: '15', label: 'Quý 3' },
  { value: '16', label: 'Quý 4' },
  { value: '17', label: '6 tháng đầu năm' },
  { value: '18', label: '6 tháng cuối năm' },
  { value: '19', label: 'Cả năm' },
];

const TEMPLATE_OPTIONS = [
  { value: 'GLTC20_TT200', label: 'TT 200/2014/TT-BTC' },
];

const DATE_TYPE_ALLOW = new Set(DATE_TYPE_OPTIONS.map(o => o.value));

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function yearOptions(): { value: string; label: string }[] {
  const y = new Date().getFullYear();
  const out: { value: string; label: string }[] = [];
  for (let i = y + 1; i >= y - 10; i -= 1) {
    out.push({ value: String(i), label: String(i) });
  }
  return out;
}

function sectionHasAccount(section: FinancialStatementNotesSection): boolean {
  return (section.items ?? []).some(it => Boolean((it.account ?? '').trim()));
}

const ThuyetMinhBctcPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const years = useMemo(() => yearOptions(), []);

  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [dateType, setDateType] = useState('19');
  const [templateCode, setTemplateCode] = useState(DEFAULT_TEMPLATE);

  const [company, setCompany] = useState<FinancialStatementNotesCompany | null>(null);
  const [sections, setSections] = useState<FinancialStatementNotesSection[]>([]);
  const [appliedYear, setAppliedYear] = useState('');
  const [appliedDateType, setAppliedDateType] = useState('');
  const [appliedTemplateCode, setAppliedTemplateCode] = useState(DEFAULT_TEMPLATE);
  const [dateTypeLabel, setDateTypeLabel] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [prevFromDate, setPrevFromDate] = useState('');
  const [prevToDate, setPrevToDate] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const draftMatchesApplied =
    hasViewed &&
    year.trim() === appliedYear &&
    dateType.trim() === appliedDateType &&
    templateCode.trim() === appliedTemplateCode;

  const handleView = useCallback(() => {
    setFilterError('');
    const companyCode = sessionCompany();
    if (!companyCode) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }

    const yearNum = Number(year.trim());
    if (!year.trim() || !Number.isFinite(yearNum) || yearNum < 1900 || yearNum > 2100) {
      setFilterError('Chọn năm báo cáo');
      dispatchAppToast(dispatch, { message: 'Chọn năm báo cáo', type: 'error' });
      return;
    }

    const dt = dateType.trim();
    if (!dt || !DATE_TYPE_ALLOW.has(dt)) {
      setFilterError('Chọn loại kỳ');
      dispatchAppToast(dispatch, { message: 'Chọn loại kỳ', type: 'error' });
      return;
    }

    const template = templateCode.trim();
    if (!template || !TEMPLATE_ALLOW.has(template)) {
      setFilterError('Chọn mẫu báo cáo');
      dispatchAppToast(dispatch, { message: 'Chọn mẫu báo cáo', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getFinancialStatementNotes({
        year: yearNum,
        dateType: dt,
        templateCode: template,
        pageSize: 0,
      })
      .then(report => {
        setCompany(report.company ?? null);
        setSections(Array.isArray(report.sections) ? report.sections : []);
        setAppliedYear(String(yearNum));
        setAppliedDateType(dt);
        setAppliedTemplateCode(template);
        setDateTypeLabel((report.meta?.dateTypeLabel || '').trim());
        setFromDate((report.meta?.fromDate || '').trim());
        setToDate((report.meta?.toDate || '').trim());
        setPrevFromDate((report.meta?.prevFromDate || '').trim());
        setPrevToDate((report.meta?.prevToDate || '').trim());
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được thuyết minh báo cáo tài chính'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dateType, dispatch, templateCode, year]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setYear(String(new Date().getFullYear()));
    setDateType('19');
    setTemplateCode(DEFAULT_TEMPLATE);
    setFilterError('');
  }, []);

  const handleExportWord = useCallback(() => {
    dispatchAppToast(dispatch, {
      message: 'Xuất Word — P1',
      type: 'info',
    });
  }, [dispatch]);

  const handlePrint = useCallback(() => {
    if (!hasViewed) return;
    window.print();
  }, [hasViewed]);

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-word',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Word',
        variant: 'secondary',
        testId: `${TEST_ID}-export-word`,
        disabled: true,
        onClick: handleExportWord,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExportWord, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle = hasViewed
    ? `Năm ${appliedYear} · ${dateTypeLabel || appliedDateType} · ${formatDate(fromDate)} – ${formatDate(toDate)} · Mẫu ${appliedTemplateCode}${
        prevFromDate && prevToDate
          ? ` · Kỳ trước: ${formatDate(prevFromDate)} – ${formatDate(prevToDate)}`
          : ''
      }${!draftMatchesApplied ? ' · (bộ lọc đã đổi — Xem lại để cập nhật)' : ''}`
    : '';

  const companyBlock =
    hasViewed && company ? (
      <dl className={styles.company} data-testid={`${TEST_ID}-company`}>
        {company.holdingName ? (
          <>
            <dt className={styles.companyDt}>Tập đoàn</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-holding`}>
              {company.holdingName}
            </dd>
          </>
        ) : null}
        {company.companyName ? (
          <>
            <dt className={styles.companyDt}>Đơn vị</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-name`}>
              {company.companyName}
            </dd>
          </>
        ) : null}
        {company.address ? (
          <>
            <dt className={styles.companyDt}>Địa chỉ</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-address`}>
              {company.address}
            </dd>
          </>
        ) : null}
        {company.taxCode ? (
          <>
            <dt className={styles.companyDt}>Mã số thuế</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-tax`}>
              {company.taxCode}
            </dd>
          </>
        ) : null}
        {company.directorName ? (
          <>
            <dt className={styles.companyDt}>Giám đốc</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-director`}>
              {company.directorName}
            </dd>
          </>
        ) : null}
        {company.chiefAccountantName ? (
          <>
            <dt className={styles.companyDt}>Kế toán trưởng</dt>
            <dd className={styles.companyDd} data-testid={`${TEST_ID}-company-cao`}>
              {company.chiefAccountantName}
            </dd>
          </>
        ) : null}
      </dl>
    ) : null;

  const result = (
    <div>
      {subtitle ? (
        <div className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed && !loading ? (
        <div className={styles.hint} data-testid={`${TEST_ID}-empty-before-view`}>
          Chọn năm, loại kỳ và mẫu rồi bấm Xem
        </div>
      ) : null}
      {companyBlock}
      {hasViewed ? (
        <div className={styles.sections} data-testid={`${TEST_ID}-sections`}>
          {sections.map(section => {
            const showAccount = sectionHasAccount(section);
            return (
              <section
                key={section.sectionCode}
                className={styles.section}
                data-testid={`${TEST_ID}-section-${section.sectionCode}`}
              >
                <h3 className={styles.sectionTitle}>
                  <span>{section.title || section.sectionCode}</span>
                  {section.isPlaceholder ? (
                    <span className={styles.placeholderBadge}>Đang bổ sung</span>
                  ) : null}
                </h3>
                <table className={reportStyles.table}>
                  <thead>
                    <tr>
                      <th>Chỉ tiêu</th>
                      {showAccount ? <th className={reportStyles.colStt}>Tài khoản</th> : null}
                      <th className={reportStyles.colRight}>Số dư đầu kỳ</th>
                      <th className={reportStyles.colRight}>Số dư cuối kỳ</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(section.items ?? []).map((item, index) => (
                      <tr key={`${section.sectionCode}|${item.mergeKey ?? ''}|${index}`}>
                        <td>{item.label}</td>
                        {showAccount ? (
                          <td className={reportStyles.colStt}>{item.account ?? ''}</td>
                        ) : null}
                        <td className={reportStyles.colRight}>
                          {formatVnd(item.openingAmount ?? 0)}
                        </td>
                        <td className={reportStyles.colRight}>
                          {formatVnd(item.closingAmount ?? 0)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </section>
            );
          })}
          {sections.length === 0 ? (
            <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
              Không có dữ liệu
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-file-alt' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-year`} onKeyDown={onEnterView}>
              <Select
                label="Năm"
                value={year}
                onChange={e => setYear(e.target.value)}
                options={years}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-dateType`} onKeyDown={onEnterView}>
              <Select
                label="Loại kỳ"
                value={dateType}
                onChange={e => setDateType(e.target.value)}
                options={DATE_TYPE_OPTIONS}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-templateCode`} onKeyDown={onEnterView}>
              <Select
                label="Mẫu báo cáo"
                value={templateCode}
                onChange={e => setTemplateCode(e.target.value)}
                options={TEMPLATE_OPTIONS}
                size="small"
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div data-testid={`${TEST_ID}-filter-error`}>{filterError}</div>
            ) : null}
          </>
        )}
      >
        {result}
      </LinPageLayout>
    </div>
  );
};

export default ThuyetMinhBctcPage;
